using System.Security.Cryptography;
using System.Text;

namespace Candela.Mvr;

/// <summary>
/// Name-based GUIDs (RFC 4122 version-5 layout over SHA-256): the same namespace and name always give the same id.
/// Used for ids that MVR does not carry (expanded symbol geometry, focus points written on export, cables created from
/// connections, assets) so that imports and exports are reproducible.
/// </summary>
internal static class DeterministicGuid
{
    /// <summary>Namespace of ids generated by this module.</summary>
    public static readonly Guid MvrNamespace = new("6d4f2b8e-31c0-4a57-9d0e-5c3a1f7e2b90");

    public static Guid Create(Guid ns, string name)
    {
        Span<byte> input = stackalloc byte[16];
        ns.TryWriteBytes(input);
        int len = Encoding.UTF8.GetByteCount(name);
        byte[] buffer = new byte[16 + len];
        input.CopyTo(buffer);
        Encoding.UTF8.GetBytes(name, 0, name.Length, buffer, 16);
        Span<byte> hash = stackalloc byte[32];
        SHA256.HashData(buffer, hash);
        var bytes = hash[..16];
        bytes[7] = (byte)((bytes[7] & 0x0F) | 0x50); // version 5 (byte order of Guid.TryWriteBytes: little-endian fields)
        bytes[8] = (byte)((bytes[8] & 0x3F) | 0x80); // RFC 4122 variant
        return new Guid(bytes);
    }

    public static Guid Create(Guid ns, string name, int index) => Create(ns, string.Concat(name, "#", index.ToString(System.Globalization.CultureInfo.InvariantCulture)));

    /// <summary>Id derived from content bytes and a name (content-addressed assets).</summary>
    public static Guid FromContent(string name, ReadOnlySpan<byte> content)
    {
        Span<byte> hash = stackalloc byte[32];
        SHA256.HashData(content, hash);
        return Create(MvrNamespace, string.Concat(name.ToLowerInvariant(), ":", Convert.ToHexString(hash)));
    }
}
